// The NEW OPERATOR (the expression)
Widget* pw = new Widget;        // Does: allocate + construct
Widget* pa = new Widget[10];    // Array form

// OPERATOR NEW (the allocation function)
void* operator new(size_t size);              // Global allocator
void* operator new(size_t size, void* ptr);   // Placement new
void* Widget::operator new(size_t size);      // Class-specific

// What the new operator does internally:
Widget* pw = new Widget(args);
// Expands to approximately:
void* memory = operator new(sizeof(Widget));  // Step 1: allocate
try {
  new (memory) Widget(args);                  // Step 2: construct (placement new)
  pw = static_cast<Widget*>(memory);
} catch (...) {
  operator delete(memory);                    // Cleanup if constructor throws
  throw;
}

// Custom operator new (overloading the allocator)
void* Widget::operator new(size_t size) {
  void* p = malloc(size);
  return p;
}

// Using just operator new (no construction)
void* raw_memory = operator new(sizeof(Widget));  // Just allocate
// Must manually construct:
new (raw_memory) Widget();  // Placement new for construction

code_example:
#include <iostream>
#include <cstdlib>

class Widget {
    int data;
public:
    Widget(int val = 0) : data(val) {
        std::cout << "Widget constructed: " << data << "\n";
    }

    ~Widget() {
        std::cout << "Widget destroyed: " << data << "\n";
    }

    // Custom operator new (allocation function)
    void* operator new(size_t size) {
        std::cout << "Custom operator new called, size: " << size << "\n";
        void* p = malloc(size);
        if (!p) throw std::bad_alloc();
        return p;
    }

    // Custom operator delete (deallocation function)
    void operator delete(void* ptr) noexcept {
        std::cout << "Custom operator delete called\n";
        free(ptr);
    }
};

int main() {
    std::cout << "=== Using new operator (does both allocation + construction) ===\n";
    Widget* pw1 = new Widget(42);  // Calls: operator new, then constructor
    delete pw1;                     // Calls: destructor, then operator delete

    std::cout << "\n=== Using operator new directly (allocation only) ===\n";
    void* raw = operator new(sizeof(Widget));  // Just allocate, no construction
    std::cout << "Memory allocated but Widget not constructed yet\n";

    // Manual construction using placement new
    Widget* pw2 = new (raw) Widget(99);  // Construct in pre-allocated memory

    // Manual destruction and deallocation
    pw2->~Widget();                      // Explicit destructor call
    operator delete(raw);                // Deallocate

    return 0;
}
